// LoansPerformanceSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/loans/performance/list/LoansPerformanceSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import LoansPerformanceActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const LoansPerformanceSchema = {
  entity: 'simukopa_loans_performance',
  label: 'Loan Performance',
  description: '',
  apiBase: apiRoutes.loansperformance?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: LoansPerformanceActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'loans', label: 'Loans Issued', from: 'loans' },
    { key: 'principal', label: 'Principal Lent', from: 'loans.principal_amount', type: 'money' },
    { key: 'interest', label: 'Interest', from: 'loans.interest_amount', type: 'money' },
    { key: 'fees', label: 'Processing Fees', from: 'loans.processing_fee', type: 'money' },
    { key: 'expected', label: 'To Be Repaid', from: 'loans.total_amount', type: 'money' },
    { key: 'deposits', label: 'Deposits Taken', from: 'loans.deposit_amount', type: 'money' },
    { key: 'balance', label: 'Still Owed', from: 'loans.balance_amount', type: 'money' },
    { key: 'defaulted', label: 'Defaulted Loans', from: 'loans' },
    { key: 'earnings', label: 'Interest and Fees', calc: 'interest + fees', type: 'money' },
    { key: 'avg_loan', label: 'Average Loan', calc: 'principal / loans', type: 'money' },
    { key: 'chg', label: 'Lent vs Previous', calc: 'change(principal)' },
  ],

  remarks: [
    { if: 'loans == 0', tone: 'watch', title: 'No loans', say: 'No loans were issued in {label}.' },
    { if: 'defaulted > 0', tone: 'bad', title: 'Defaults', say: '{defaulted} of the {loans} loans issued in {label} have defaulted, with {balance} still owed.' },
    { if: 'chg !== null && chg <= -20', tone: 'watch', title: 'Lending dropped', say: '{label}: {principal} lent, down {abs(chg)}% on {prev_label}.' },
    { if: 'true', tone: 'neutral', title: 'Loan activity', say: '{loans} loans worth {principal} issued, with {earnings} in interest and fees.' },
  ],

  headline: '{label}: {loans} loans issued, {principal} lent[, {updown} {abs(chg)}% on {prev_label}].',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'loans', next: 10, method: 'auto', integer: true }, { key: 'principal', next: 10, method: 'auto', integer: false }],
};
